import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string; status: JobStatus; input: string; steps: number; failAttempts: number; attempts: number;
  progress: { completed: number; total: number }; result: { output: string } | null; error: string | null;
  createdAt: string; updatedAt: string;
}
export interface JobRow {
  id: string; status: JobStatus; input: string; steps: number; fail_attempts: number; attempts: number;
  progress_completed: number; result_output: string | null; error: string | null; created_at: string; updated_at: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, next_attempt_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_created_idx ON jobs(created_at DESC);
    CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs(status, next_attempt_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK (id = 1), updated_at INTEGER NOT NULL);`);
  return db;
}

export function fromRow(row: JobRow): Job {
  return { id: row.id, status: row.status, input: row.input, steps: row.steps, failAttempts: row.fail_attempts,
    attempts: row.attempts, progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null, createdAt: row.created_at, updatedAt: row.updated_at };
}

export function nowIso(): string { return new Date().toISOString(); }

