import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, fromRow, nowIso, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: Array<{field:string;message:string}>): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = ''; let size = 0;
  for await (const chunk of req) { size += Buffer.byteLength(chunk); if (size > 1_000_000) throw new Error('too_large'); body += chunk; }
  return body;
}
const getJob = db.prepare('SELECT * FROM jobs WHERE id = ?');

async function submit(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: Array<{field:string;message:string}> = [];
  if (!/^application\/json(?:\s*;|\s*$)/i.test(req.headers['content-type'] ?? '')) {
    error(res, 400, 'invalid_request', 'Request must use Content-Type: application/json.', [{ field: 'body', message: 'must be JSON' }]); return;
  }
  let parsed: unknown;
  try { parsed = JSON.parse(await readBody(req)); }
  catch { error(res, 400, 'invalid_request', 'Request body must be valid JSON.', [{ field: 'body', message: 'must be valid JSON' }]); return; }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    error(res, 400, 'invalid_request', 'Request body must be an object.', [{ field: 'body', message: 'must be an object' }]); return;
  }
  const body = parsed as Record<string, unknown>;
  for (const k of Object.keys(body)) if (!['input','steps','failAttempts'].includes(k)) fields.push({ field:k, message:'is not allowed' });
  const input = body.input;
  if (typeof input !== 'string') fields.push({ field:'input', message:'must be a string' });
  else if (input.length < 1 || input.length > 1000 || !input.trim()) fields.push({ field:'input', message:'must be 1–1000 characters and not only whitespace' });
  const steps = body.steps === undefined ? 5 : body.steps;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field:'steps', message:'must be an integer from 1 to 20' });
  const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field:'failAttempts', message:'must be an integer from 0 to 5' });
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined && (Array.isArray(keyHeader) || !/^[A-Za-z0-9_-]{1,128}$/.test(keyHeader))) fields.push({ field:'Idempotency-Key', message:'must contain 1–128 letters, numbers, underscores, or hyphens' });
  if (fields.length) { error(res, 400, 'invalid_request', 'Request validation failed.', fields); return; }
  const key = typeof keyHeader === 'string' ? keyHeader : undefined;
  const validInput = input as string; const validSteps = steps as number; const validFailAttempts = failAttempts as number;
  const payload = JSON.stringify({ input: validInput, steps: validSteps, failAttempts: validFailAttempts });
  if (key) {
    const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as {payload:string;job_id:string} | undefined;
    if (prior) {
      if (prior.payload !== payload) { error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.'); return; }
      const row = getJob.get(prior.job_id) as unknown as JobRow | undefined;
      if (row) { send(res, 200, fromRow(row)); return; }
    }
  }
  const id = randomUUID(); const timestamp = nowIso();
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key) {
      const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as {payload:string;job_id:string} | undefined;
      if (prior) {
        db.exec('COMMIT');
        if (prior.payload !== payload) { error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.'); return; }
      const row = getJob.get(prior.job_id) as unknown as JobRow | undefined;
        if (row) { send(res, 200, fromRow(row)); return; }
      }
    }
    db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
      VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, validInput, validSteps, validFailAttempts, timestamp, timestamp);
    if (key) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  send(res, 201, fromRow(getJob.get(id) as unknown as JobRow));
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/') {
    if (req.method !== 'GET') { error(res,405,'method_not_allowed','Method not allowed.'); return; }
    res.writeHead(200, { 'content-type':'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') { error(res,405,'method_not_allowed','Method not allowed.'); return; }
    const heart = db.prepare('SELECT updated_at FROM worker_heartbeat WHERE id = 1').get() as {updated_at:number} | undefined;
    send(res,200,{status:'ok',worker:heart && Date.now()-heart.updated_at < 3000 ? 'up' : 'down'}); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'POST') { try { await submit(req,res); } catch { error(res,500,'internal_error','Unable to process request.'); } return; }
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as JobRow[];
      send(res,200,{jobs:rows.map(fromRow)}); return;
    }
    error(res,405,'method_not_allowed','Method not allowed.'); return;
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') { error(res,405,'method_not_allowed','Method not allowed.'); return; }
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { error(res,404,'not_found','Job not found.'); return; }
    const row = getJob.get(id) as unknown as JobRow | undefined;
    if (!row) { error(res,404,'not_found','Job not found.'); return; }
    send(res,200,fromRow(row)); return;
  }
  error(res,404,'not_found','Not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
let shuttingDown = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => {
  if (shuttingDown) return; shuttingDown = true;
  server.close(() => { db.close(); process.exit(0); });
  setTimeout(() => { db.close(); process.exit(0); }, 2000).unref();
});

