import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that is no longer alive when this process starts.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=? WHERE status='running'").run(nowIso());
const heartbeat = db.prepare('INSERT INTO worker_heartbeat(id,updated_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET updated_at=excluded.updated_at');
const claim = (): JobRow | undefined => {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND next_attempt_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as unknown as JobRow | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const timestamp = nowIso();
    db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, error=NULL, updated_at=? WHERE id=? AND status='queued'").run(timestamp,row.id);
    db.exec('COMMIT');
    return db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id) as unknown as JobRow;
  } catch (e) { db.exec('ROLLBACK'); throw e; }
};

console.log('worker started');
while (!stopping) {
  heartbeat.run(Date.now());
  const job = claim();
  if (!job) { await sleep(100); continue; }
  if (job.attempts <= job.fail_attempts) {
    const timestamp = nowIso();
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=? AND status='running'").run(timestamp,job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, next_attempt_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now()+500,timestamp,job.id);
    }
    continue;
  }
  for (let step=1; step<=job.steps; step++) {
    await sleep(100);
    if (stopping) break;
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step,nowIso(),job.id);
  }
  if (stopping) break;
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(),nowIso(),job.id);
}
db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
db.close();

