40	    const form = document.querySelector('[data-testid="job-form"]');
41	    const errorRegion = document.querySelector('[data-testid="form-error"]');
42	    const list = document.querySelector('[data-testid="job-list"]');
43	    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
44	    function showJobs(jobs) {
45	      list.innerHTML = jobs.map((job) => {
46	        const result = job.result ? job.result.output : job.status === 'failed' ? job.error : '';
47	        return `<li class="job" data-testid="job-item" data-job-id="${escapeHtml(job.id)}">
