51	          <div class="result" data-testid="job-result">${escapeHtml(result)}</div>
52	        </li>`;
53	      }).join('');
54	    }
55	    async function refresh() {
56	      try { const response = await fetch('/api/jobs'); if (response.ok) showJobs((await response.json()).jobs); }
57	      catch { /* the next poll will refresh after a temporary connection issue */ }
58	    }
59	    form.addEventListener('submit', async (event) => {
60	      event.preventDefault(); errorRegion.textContent = '';
61	      const button = form.querySelector('button'); button.disabled = true;
62	      const input = document.querySelector('[data-testid="job-input"]').value;
63	      const stepsText = document.querySelector('[data-testid="job-steps"]').value;
64	      const failuresText = document.querySelector('[data-testid="job-fail-attempts"]').value;
65	      const payload = { input, steps: Number(stepsText), failAttempts: Number(failuresText) };
66	      try {
67	        const response = await fetch('/api/jobs', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify(payload) });
68	        const data = await response.json();
69	        if (!response.ok) {
70	          const detail = data.error?.fields?.map((item) => `${item.field}: ${item.message}`).join('; ');
71	          errorRegion.textContent = detail || data.error?.message || 'The job could not be submitted.';
72	        } else { form.elements.input.value = ''; await refresh(); }
73	      } catch { errorRegion.textContent = 'Unable to reach the server.'; }
74	      finally { button.disabled = false; }
75	    });
76	    refresh(); setInterval(refresh, 700);
77	  </script>
